1	// SAM v2 strict-profile spec of one payment in src/host.impl.ts.
2	// `pending` counts authorisation requests sent and not yet answered; COMPLETE
3	// answers one of them (which one does not matter: they are interchangeable).
4	const { createInstance } = require('@cognitive-fab/sam-pattern');
5	
6	const MAX_REQUESTS = 3;
7	const INITIAL_STATE = { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending: 0 };
8	const isUnit = (a) => a === 1 || a === 2;
9	const AMOUNTS = [{ amount: 0 }, { amount: 1 }, { amount: 2 }, { amount: 3 }];
10	
11	const instance = createInstance({ strict: true, hasAsyncActions: false });
12	
13	const modelShape = {
14	  status: { type: 'string' },
15	  authorized: { type: 'number' },
16	  captured: { type: 'number' },
17	  refunded: { type: 'number' },
18	  requests: { type: 'number' },
19	  pending: { type: 'number' },
20	};
21	
22	const actions = {
23	  AUTHORIZE: { action: (data = {}) => ({ ...data }), schema: { amount: { type: 'number', required: true } }, domain: AMOUNTS },
