  AUTHORIZE: { action: (data = {}) => ({ ...data }), schema: { amount: { type: 'number', required: true } }, domain: AMOUNTS },
  TIMED_OUT: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
  CAPTURE: { action: (data = {}) => ({ ...data }), schema: { amount: { type: 'number', required: true } }, domain: AMOUNTS },
