const MONEY = ['captured', 'refunded'];

export const stateInvariants = [
  { name: 'captured-within-authorised', pred: (s) => s.captured <= s.authorized },
  { name: 'refunded-within-captured', pred: (s) => s.refunded <= s.captured },
  { name: 'at-most-3-requests', pred: (s) => s.requests <= 3 },
  { name: 'voided-captured-nothing', pred: (s) => s.status !== 'voided' || (s.captured === 0 && s.refunded === 0) },
  { name: 'nothing-captured-before-capture', pred: (s) => ['captured', 'refunded'].includes(s.status) || (s.captured === 0 && s.refunded === 0) },
  { name: 'refunded-means-all-refunded', pred: (s) => s.status !== 'refunded' || (s.captured > 0 && s.refunded === s.captured) },
  { name: 'captured-means-not-all-refunded', pred: (s) => s.status !== 'captured' || (s.captured > 0 && s.refunded < s.captured) },
  { name: 'authorised-amount-is-1-or-2', pred: (s) => (s.status === 'none' ? s.authorized === 0 : s.authorized === 1 || s.authorized === 2) },
  { name: 'pending-within-requests', pred: (s) => s.pending >= 0 && s.pending <= s.requests },
  { name: 'failed-only-after-3-requests', pred: (s) => s.status !== 'failed' || s.requests === 3 },
];

