  {
    name: 'money-moves-only-by-capture-or-refund',
    pred: (pre, action, _d, post) =>
      MONEY.every((k) => post[k] === pre[k]) ||
      (action === 'CAPTURE' && post.refunded === pre.refunded) ||
      (action === 'REFUND' && post.captured === pre.captured),
  },
  {
    name: 'refunds-only-grow',
    pred: (pre, _a, _d, post) => post.refunded >= pre.refunded,
  },
  {
    name: 'only-an-answer-or-timeout-leaves-authorizing',
    pred: (pre, action, _d, post) =>
      pre.status !== 'authorizing' || post.status === 'authorizing' || action === 'COMPLETE' || action === 'TIMED_OUT',
  },
  {
    name: 'answer-decides-only-while-authorizing',
    pred: (pre, action, _d, post) => action !== 'COMPLETE' || pre.status === 'authorizing' || post.status === pre.status,
