// Drives src/host.impl.ts through scenarios for one payment and writes one
// NDJSON trace per scenario: {pre, action, data, post} in the contract's state.
// Usage: node spec/capture.mjs  (writes spec/traces/*.ndjson)
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';

const P = 'pay';
const dir = new URL('./traces/', import.meta.url);

async function observe(h) {
  const v = await h.payment(P);
  const pending = (await h.pendingEffects()).filter((e) => e.from === P).length;
  if (!v) return { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending };
  return { ...v, pending };
}

async function step(h, action, data) {
  switch (action) {
    case 'AUTHORIZE': return h.authorize(P, data.amount);
    case 'TIMED_OUT': return h.timedOut(P);
    case 'CAPTURE': return h.capture(P, data.amount);
    case 'VOID': return h.void(P);
    case 'REFUND': return h.refund(P, data.amount);
    case 'COMPLETE': {
      const [e] = (await h.pendingEffects()).filter((x) => x.from === P);
      if (e) await h.completeEffect(e.id, data.outcome);
      return;
    }
  }
}

async function run(name, script) {
  const h = await createHost();
  const lines = [];
  for (const [action, data = {}] of script) {
    const pre = await observe(h);
    await step(h, action, data);
    lines.push(JSON.stringify({ pre, action, data, post: await observe(h) }));
  }
  writeFileSync(new URL(`${name}.ndjson`, dir), lines.join('\n') + '\n');
}

const A = (amount) => ['AUTHORIZE', { amount }];
const C = (amount) => ['CAPTURE', { amount }];
const R = (amount) => ['REFUND', { amount }];
const OK = ['COMPLETE', { outcome: 'ok' }];
const NO = ['COMPLETE', { outcome: 'failed' }];
const T = ['TIMED_OUT'];
const V = ['VOID'];

const scenarios = {
  happy: [A(2), OK, C(2), R(1), R(1), R(1)],
  partial: [A(2), OK, C(1), R(2), R(1), C(1)],
  void: [V, A(1), C(1), OK, C(2), V, V, C(1), R(1)],
  declined: [A(1), NO, OK, C(1), T, V],
  retries: [A(2), T, T, T, T, OK, NO, OK, NO, T],
  retryThenApprove: [A(1), T, NO, OK, C(1), R(1), R(1)],
  badInputs: [C(1), R(1), T, NO, A(0), A(3), A(1), A(2), C(0), OK, C(3), R(1), C(1), R(0), R(3), R(2), R(1)],
  lateAnswers: [A(2), T, OK, NO, T, C(2), R(2), A(1)],
};

rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, script] of Object.entries(scenarios)) await run(name, script);
console.log(`wrote ${Object.keys(scenarios).length} traces`);

