import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const effectsOf = async (h, p) => (await h.pendingEffects()).filter((e) => e.from === p);
const approve = async (h, p, outcome = 'ok') => {
  const [e] = await effectsOf(h, p);
  await h.completeEffect(e.id, outcome);
};

test('authorize creates an authorizing payment and one request', async () => {
  const h = await createHost();
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'authorizing', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.deepEqual({ ...effs[0], id: undefined }, { id: undefined, from: 'p', kind: 'card.authorize', data: { amount: 2 } });
  assert.equal((await h.authorize('p', 1)).ok, false);
  assert.equal((await h.authorize('q', 3)).ok, false);
  assert.equal((await h.authorize('q', 0)).ok, false);
  assert.equal(await h.payment('q'), null);
});

test('unknown payments are refused', async () => {
  const h = await createHost();
  for (const r of [await h.timedOut('x'), await h.capture('x', 1), await h.void('x'), await h.refund('x', 1)]) {
    assert.equal(r.ok, false);
    assert.equal(typeof r.reason, 'string');
  }
});

test('timeouts retry up to 3 requests then fail; late answers ignored', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.payment('p')).requests, 3);
  assert.equal((await h.pendingEffects()).length, 3);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.payment('p')).status, 'failed');
  assert.equal((await h.payment('p')).requests, 3);
  assert.equal((await h.timedOut('p')).ok, false);
  await approve(h, 'p');
  assert.equal((await h.payment('p')).status, 'failed');
  assert.equal((await h.pendingEffects()).length, 2);
});

test('first answer decides', async () => {
  const h = await createHost();
  await h.authorize('p', 2);
  await h.timedOut('p');
  const [a, b] = await h.pendingEffects();
  await h.completeEffect(b.id, 'failed');
  assert.equal((await h.payment('p')).status, 'declined');
  await h.completeEffect(a.id, 'ok');
  assert.equal((await h.payment('p')).status, 'declined');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.capture('p', 1)).ok, false);
});

test('capture, partial refunds, full refund', async () => {
  const h = await createHost();
  await h.authorize('p', 2);
  assert.equal((await h.capture('p', 1)).ok, false);
  await approve(h, 'p');
  assert.equal((await h.timedOut('p')).ok, false);
  assert.equal((await h.refund('p', 1)).ok, false);
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.equal((await h.capture('p', 2)).ok, true);
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.void('p')).ok, false);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.deepEqual(await h.payment('p'), { status: 'captured', authorized: 2, captured: 2, refunded: 1, requests: 1 });
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.equal((await h.payment('p')).status, 'refunded');
  assert.equal((await h.refund('p', 1)).ok, false);
});

test('capture beyond authorised is refused; void', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  await approve(h, 'p');
  assert.equal((await h.capture('p', 2)).ok, false);
  assert.equal((await h.void('p')).ok, true);
  assert.deepEqual(await h.payment('p'), { status: 'voided', authorized: 1, captured: 0, refunded: 0, requests: 1 });
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.void('p')).ok, false);
});

test('fresh hosts are independent', async () => {
  const a = await createHost();
  await a.authorize('p', 1);
  const b = await createHost();
  assert.equal(await b.payment('p'), null);
  assert.deepEqual(await b.pendingEffects(), []);
});

test('increase raises an authorized, uncaptured payment by 1 up to 3', async () => {
  const h = await createHost();
  assert.equal((await h.increase('p')).ok, false);
  await h.authorize('p', 2);
  assert.equal((await h.increase('p')).ok, false);
  await approve(h, 'p');
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.equal((await h.increase('p')).ok, true);
  assert.equal((await h.payment('p')).authorized, 3);
  assert.equal((await h.increase('p')).ok, false);
  assert.equal((await h.payment('p')).authorized, 3);
  assert.equal((await h.capture('p', 4)).ok, false);
  assert.equal((await h.capture('p', 3)).ok, true);
  assert.equal((await h.increase('p')).ok, false);
  assert.equal((await h.refund('p', 3)).ok, false);
  assert.equal((await h.refund('p', 2)).ok, true);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 3, captured: 3, refunded: 3, requests: 1 });
});

test('expire: an authorized, uncaptured payment expires and accepts nothing more', async () => {
  const h = await createHost();
  assert.equal((await h.expire('p')).ok, false);
  await h.authorize('p', 1);
  await h.timedOut('p');
  assert.equal((await h.expire('p')).ok, false);
  await approve(h, 'p');
  await h.increase('p');
  assert.equal((await h.expire('p')).ok, true);
  assert.deepEqual(await h.payment('p'), { status: 'expired', authorized: 2, captured: 0, refunded: 0, requests: 2 });
  for (const r of [await h.expire('p'), await h.capture('p', 1), await h.void('p'), await h.increase('p'),
    await h.refund('p', 1), await h.timedOut('p'), await h.authorize('p', 1)]) assert.equal(r.ok, false);
  await approve(h, 'p');
  assert.equal((await h.payment('p')).status, 'expired');
});

test('captured and voided payments do not expire', async () => {
  const h = await createHost();
  await h.authorize('c', 2);
  await approve(h, 'c');
  await h.capture('c', 1);
  assert.equal((await h.expire('c')).ok, false);
  assert.equal((await h.payment('c')).status, 'captured');
  await h.refund('c', 1);
  assert.equal((await h.expire('c')).ok, false);
  await h.authorize('v', 1);
  await approve(h, 'v');
  await h.void('v');
  assert.equal((await h.expire('v')).ok, false);
  await h.authorize('d', 1);
  await approve(h, 'd', 'failed');
  assert.equal((await h.expire('d')).ok, false);
});

test('increase refused on voided payments', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  await approve(h, 'p');
  await h.void('p');
  assert.equal((await h.increase('p')).ok, false);
  assert.equal((await h.payment('p')).authorized, 1);
});

