tool_use_result.originalFile:
// The rules the brief requires of one payment ("money moves only as the brief allows").
const MONEY = ['captured', 'refunded'];

export const stateInvariants = [
  { name: 'captured-within-authorised', pred: (s) => s.captured <= s.authorized },
  { name: 'refunded-within-captured', pred: (s) => s.refunded <= s.captured },
  { name: 'at-most-3-requests', pred: (s) => s.requests <= 3 },
  { name: 'voided-captured-nothing', pred: (s) => s.status !== 'voided' || (s.captured === 0 && s.refunded === 0) },
  { name: 'expired-captured-nothing', pred: (s) => s.status !== 'expired' || (s.captured === 0 && s.refunded === 0) },
  { name: 'nothing-captured-before-capture', pred: (s) => ['captured', 'refunded'].includes(s.status) || (s.captured === 0 && s.refunded === 0) },
  { name: 'refunded-means-all-refunded', pred: (s) => s.status !== 'refunded' || (s.captured > 0 && s.refunded === s.captured) },
  { name: 'captured-means-not-all-refunded', pred: (s) => s.status !== 'captured' || (s.captured > 0 && s.refunded < s.captured) },
  { name: 'authorised-amount-is-1-to-3', pred: (s) => (s.status === 'none' ? s.authorized === 0 : s.authorized >= 1 && s.authorized <= 3) },
  { name: 'captured-is-0-to-3', pred: (s) => s.captured >= 0 && s.captured <= 3 },
  { name: 'pending-within-requests', pred: (s) => s.pending >= 0 && s.pending <= s.requests },
  { name: 'failed-only-after-3-requests', pred: (s) => s.status !== 'failed' || s.requests === 3 },
];

export const transitionInvariants = [
  {
    name: 'authorised-amount-changes-only-by-increase',
    pred: (pre, action, _d, post) =>
      pre.status === 'none' ||
      post.authorized === pre.authorized ||
      (action === 'INCREASE' && pre.status === 'authorized' && post.authorized === pre.authorized + 1),
  },
  {
    name: 'no-increase-after-capture',
    pred: (pre, _a, _d, post) => pre.captured === 0 || post.authorized === pre.authorized,
  },
  {
    name: 'money-moves-only-by-capture-or-refund',
    pred: (pre, action, _d, post) =>
      MONEY.every((k) => post[k] === pre[k]) ||
      (action === 'CAPTURE' && post.refunded === pre.refunded) ||
      (action === 'REFUND' && post.captured === pre.captured),
  },
  {
    name: 'expired-accepts-nothing',
    pred: (pre, action, _d, post) =>
      pre.status !== 'expired' || ['status', 'authorized', 'captured', 'refunded', 'requests'].every((k) => post[k] === pre[k]),
  },
  {
    name: 'only-authorized-expires',
    pred: (pre, _a, _d, post) => post.status !== 'expired' || pre.status === 'expired' || pre.status === 'authorized',
  },
  {
    name: 'refunds-only-grow',
    pred: (pre, _a, _d, post) => post.refunded >= pre.refunded,
  },
  {
    name: 'only-an-answer-or-timeout-leaves-authorizing',
    pred: (pre, action, _d, post) =>
      pre.status !== 'authorizing' || post.status === 'authorizing' || action === 'COMPLETE' || action === 'TIMED_OUT',
  },
  {
    name: 'answer-decides-only-while-authorizing',
    pred: (pre, action, _d, post) => action !== 'COMPLETE' || pre.status === 'authorizing' || post.status === pre.status,
  },
  {
    name: 'requests-sent-only-while-authorizing',
    pred: (pre, _a, _d, post) => post.requests === pre.requests || pre.status === 'authorizing' || pre.status === 'none',
  },
];

// Drives src/host.impl.ts through scenarios for one payment and writes one
// NDJSON trace per scenario: {pre, action, data, post} in the contract's state.
// Usage: node spec/capture.mjs  (writes spec/traces/*.ndjson)
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';

const P = 'pay';
const dir = new URL('./traces/', import.meta.url);

async function observe(h) {
  const v = await h.payment(P);
  const pending = (await h.pendingEffects()).filter((e) => e.from === P).length;
  if (!v) return { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending };
  return { ...v, pending };
}

async function step(h, action, data) {
  switch (action) {
    case 'AUTHORIZE': return h.authorize(P, data.amount);
    case 'TIMED_OUT': return h.timedOut(P);
    case 'CAPTURE': return h.capture(P, data.amount);
    case 'VOID': return h.void(P);
    case 'INCREASE': return h.increase(P);
    case 'EXPIRE': return h.expire(P);
    case 'REFUND': return h.refund(P, data.amount);
    case 'COMPLETE': {
      const [e] = (await h.pendingEffects()).filter((x) => x.from === P);
      if (e) await h.completeEffect(e.id, data.outcome);
      return;
    }
  }
}

async function run(name, script) {
  const h = await createHost();
  const lines = [];
  for (const [action, data = {}] of script) {
    const pre = await observe(h);
    await step(h, action, data);
    lines.push(JSON.stringify({ pre, action, data, post: await observe(h) }));
  }
  writeFileSync(new URL(`${name}.ndjson`, dir), lines.join('\n') + '\n');
}

const A = (amount) => ['AUTHORIZE', { amount }];
const C = (amount) => ['CAPTURE', { amount }];
const R = (amount) => ['REFUND', { amount }];
const OK = ['COMPLETE', { outcome: 'ok' }];
const NO = ['COMPLETE', { outcome: 'failed' }];
const T = ['TIMED_OUT'];
const V = ['VOID'];
const I = ['INCREASE'];
const E = ['EXPIRE'];

const scenarios = {
  happy: [A(2), OK, C(2), R(1), R(1), R(1)],
  partial: [A(2), OK, C(1), R(2), R(1), C(1)],
  void: [V, A(1), C(1), OK, C(2), V, V, C(1), R(1)],
  declined: [A(1), NO, OK, C(1), T, V],
  retries: [A(2), T, T, T, T, OK, NO, OK, NO, T],
  retryThenApprove: [A(1), T, NO, OK, C(1), R(1), R(1)],
  badInputs: [C(1), R(1), T, NO, A(0), A(3), A(1), A(2), C(0), OK, C(3), R(1), C(1), R(0), R(3), R(2), R(1)],
  increase: [I, A(1), I, OK, I, I, I, C(4), C(3), I, R(3), R(2), R(1), I],
  increaseThenVoid: [A(2), OK, I, I, V, I, C(1)],
  increasePartial: [A(1), T, OK, I, C(2), I, R(1), R(1)],
  expire: [E, A(2), E, T, E, OK, I, E, E, C(1), V, I, R(1), T, NO, A(1)],
  noExpireAfterCapture: [A(1), OK, C(1), E, R(1), E],
  noExpireDeclined: [A(1), NO, E, OK, E],
  lateAnswers: [A(2), T, OK, NO, T, C(2), R(2), A(1)],
};

rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, script] of Object.entries(scenarios)) await run(name, script);
console.log(`wrote ${Object.keys(scenarios).length} traces`);

